import re
from datetime import datetime

_GMAIL_DOMAINS = {"gmail.com", "googlemail.com"}
_DATE_FORMATS = ("%Y-%m-%dT%H:%M:%S", "%Y-%m-%d", "%m/%d/%Y")
_EXT_RE = re.compile(r"ext|x|#", re.IGNORECASE)
_ZIP4_RE = re.compile(r"[0-9]{4,5}-[0-9]{4}")
_OPT_OUT_VALUES = {"y", "yes", "true", "1"}


def _normalize_email(raw):
    s = (raw or "").strip()
    m = re.search(r"<([^<>]*)>", s)
    if m:
        s = m.group(1)
    s = s.strip().lower()
    if s.count("@") == 1:
        local, domain = s.split("@")
        if domain in _GMAIL_DOMAINS:
            local = local.split("+", 1)[0].replace(".", "")
            domain = "gmail.com"
        s = f"{local}@{domain}"
    return s


def _is_valid_email(s):
    if s.count("@") != 1:
        return False
    local, domain = s.split("@")
    return (bool(local) and "." in domain
            and not domain.startswith(".") and not domain.endswith("."))


def _normalize_phone(raw):
    s = raw or ""
    m = _EXT_RE.search(s)
    if m:
        s = s[:m.start()]
    digits = re.sub(r"[^0-9]", "", s)
    if len(digits) == 11 and digits[0] == "1":
        digits = digits[1:]
    return digits


def _is_valid_phone(digits):
    return len(digits) == 10 and digits[0] not in "01"


def _normalize_zip(raw):
    s = (raw or "").strip()
    if _ZIP4_RE.fullmatch(s):
        s = s.split("-", 1)[0]
    if re.fullmatch(r"[0-9]{4}", s):
        s = "0" + s
    return s if re.fullmatch(r"[0-9]{5}", s) else ""


def _normalize_name(raw):
    s = (raw or "").strip()
    if s.isupper() or s.islower():
        s = s.title()
    return s


def _parse_updated(raw):
    s = (raw or "").strip()
    for fmt in _DATE_FORMATS:
        try:
            return datetime.strptime(s, fmt)
        except ValueError:
            pass
    raise ValueError(f"Unrecognized 'updated' value: {raw!r}")


def _parse_tags(raw):
    return {t.strip().lower() for t in re.split(r"[;,]", raw or "") if t.strip()}


def dedupe_contacts(rows):
    # Step 1: normalize each row and drop rows with no valid email or phone (rule 9).
    records = []
    for idx, row in enumerate(rows):
        email = _normalize_email(row.get("email"))
        phone = _normalize_phone(row.get("phone"))
        rec = {
            "index": idx,
            "first_name": _normalize_name(row.get("first_name")),
            "last_name": _normalize_name(row.get("last_name")),
            "zip": _normalize_zip(row.get("zip")),
            "email": email if _is_valid_email(email) else "",
            "phone": phone if _is_valid_phone(phone) else "",
            "source": (row.get("source") or "").strip().lower(),
            "tags": _parse_tags(row.get("tags")),
            "opted_out": (row.get("opted_out") or "").strip().lower() in _OPT_OUT_VALUES,
            "updated": _parse_updated(row.get("updated")),
        }
        if not rec["email"] and not rec["phone"]:
            continue
        records.append(rec)

    # Step 2: union-find over matching keys (rule 10, transitive).
    parent = list(range(len(records)))

    def find(i):
        while parent[i] != i:
            parent[i] = parent[parent[i]]
            i = parent[i]
        return i

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            if ra < rb:
                parent[rb] = ra
            else:
                parent[ra] = rb

    first_seen = {}

    def link(key, i):
        if key in first_seen:
            union(first_seen[key], i)
        else:
            first_seen[key] = i

    for i, r in enumerate(records):
        if r["email"]:
            link(("email", r["email"]), i)
        if r["phone"] and r["last_name"]:
            link(("phone", r["phone"], r["last_name"].casefold()), i)

    # Step 3: group rows by person, ordered by earliest input row.
    groups = {}
    order = []
    for i in range(len(records)):
        root = find(i)
        if root not in groups:
            groups[root] = []
            order.append(root)
        groups[root].append(records[i])

    # Step 4: choose a value for each field.
    # Preference: source == "manual", then most recent updated, then earlier input row.
    def pick(group, field):
        cands = [r for r in group if r[field]]
        cands.sort(key=lambda r: r["index"])                            # earliest row
        cands.sort(key=lambda r: r["updated"], reverse=True)            # most recent
        cands.sort(key=lambda r: 0 if r["source"] == "manual" else 1)   # manual first
        return cands[0][field] if cands else ""

    people = []
    for root in order:
        group = groups[root]
        tags = set()
        for r in group:
            tags |= r["tags"]
        people.append({
            "first_name": pick(group, "first_name"),
            "last_name": pick(group, "last_name"),
            "zip": pick(group, "zip"),
            "email": pick(group, "email"),
            "phone": pick(group, "phone"),
            "source": pick(group, "source"),
            "tags": ";".join(sorted(tags)),
            "opted_out": "Y" if any(r["opted_out"] for r in group) else "N",
            "updated": max(r["updated"] for r in group).strftime("%Y-%m-%d"),
        })
    return people
